//! EPUB engine integration tests: fixtures, rbook-backed loader, CSS subset and the
//! XHTML → `BlockModel` walker.
//!
//! Fixtures are deterministic ZIP files generated by `node scripts/make-fixtures.js`
//! and committed under `tests/fixtures/`.

use std::path::{Path, PathBuf};

fn fixture(name: &str) -> PathBuf {
    Path::new("tests/fixtures").join(name)
}

#[test]
fn fixtures_exist_and_are_zip_containers() {
    for name in ["minimal2.epub", "minimal3.epub", "styled.epub", "vietnamese.epub"] {
        let path = fixture(name);
        let bytes = std::fs::read(&path)
            .unwrap_or_else(|_| panic!("missing {path:?}; run node scripts/make-fixtures.js"));
        assert_eq!(&bytes[0..2], b"PK", "{name} is not a zip");
        assert!(bytes.len() > 400, "{name} suspiciously small");
    }
}

// ---------------------------------------------------------------------------
// Task 6 — rbook-backed loader
// ---------------------------------------------------------------------------

use epub_reader::epub::{Book, SpineItem, derive_toc_from_spine};

#[test]
fn opens_epub2_fixture() {
    let book = Book::open(&fixture("minimal2.epub")).expect("minimal2 opens");
    assert!(book
        .metadata()
        .title
        .as_deref()
        .unwrap_or("")
        .contains("Minimal 2"));
    assert_eq!(book.chapter_count(), 3);
    assert!(!book.toc().is_empty());
    assert_eq!(book.toc()[0].depth, 0);
    assert!(book.toc().iter().any(|t| t.label.contains("Chapter 2")));
    // The nested NCX entry is one level deeper and maps back to chapter 0.
    let nested = book
        .toc()
        .iter()
        .find(|t| t.label.contains("Section 1"))
        .expect("nested toc entry present");
    assert_eq!(nested.depth, 1);
    assert_eq!(nested.chapter_index, Some(0));
}

#[test]
fn opens_epub3_fixture_and_finds_cover() {
    let book = Book::open(&fixture("minimal3.epub")).expect("minimal3 opens");
    assert_eq!(book.chapter_count(), 3);
    assert!(
        book.cover_png().is_some(),
        "EPUB3 cover-image property not detected"
    );
    assert!(book.cover_png().is_some_and(|b| b.starts_with(b"\x89PNG")));
    // EPUB3 nav.xhtml TOC is used when no NCX exists.
    assert_eq!(book.toc().len(), 3);
    assert_eq!(book.toc()[1].label, "Chapter 2");
    assert_eq!(book.toc()[1].chapter_index, Some(1));
}

#[test]
fn loader_exposes_metadata_and_package_relative_spine() {
    let book = Book::open(&fixture("minimal2.epub")).expect("minimal2 opens");
    assert_eq!(book.metadata().title.as_deref(), Some("Minimal 2 EPUB"));
    assert_eq!(book.metadata().authors, vec!["Test Author".to_string()]);
    let hrefs: Vec<&str> = book.spine().iter().map(|s| s.href.as_str()).collect();
    assert_eq!(hrefs, vec!["c1.xhtml", "c2.xhtml", "c3.xhtml"]);
    assert_eq!(book.spine_href(1), "c2.xhtml");
    assert_eq!(book.spine_href(99), "");
}

#[test]
fn no_toc_falls_back_to_spine_chapters() {
    let fallback = derive_toc_from_spine(&[
        SpineItem {
            href: "OEBPS/c1.xhtml".into(),
            title_hint: String::new(),
        },
        SpineItem {
            href: "OEBPS/c2.xhtml".into(),
            title_hint: String::new(),
        },
    ]);
    assert_eq!(fallback.len(), 2);
    assert_eq!(fallback[0].label, "Chapter 1");
    assert_eq!(fallback[1].chapter_index, Some(1));
    assert_eq!(fallback[0].depth, 0);
}

#[test]
fn resolves_relative_image_paths() {
    use epub_reader::epub::util::{normalize_package_path, percent_decode};
    assert_eq!(percent_decode("a%20b.png"), "a b.png");
    assert_eq!(
        normalize_package_path("OEBPS/Text", "../Images/c%20over.png"),
        "OEBPS/Images/c over.png"
    );
    assert_eq!(
        normalize_package_path("OEBPS", "./Images/x.png#frag"),
        "OEBPS/Images/x.png"
    );
}

#[test]
fn synthetic_epub_without_toc_falls_back_to_spine() {
    let manifest = [
        item_xml("c1", "c1.xhtml", "application/xhtml+xml"),
        item_xml("c2", "c2.xhtml", "application/xhtml+xml"),
    ]
    .concat();
    let spine = ["<itemref idref=\"c1\"/>", "<itemref idref=\"c2\"/>"].concat();
    let path = temp_epub(
        "no-toc",
        &opf2("No TOC", &manifest, &spine),
        &[
            ("OEBPS/c1.xhtml", chapter_bytes("One")),
            ("OEBPS/c2.xhtml", chapter_bytes("Two")),
        ],
    );
    let book = Book::open(&path).expect("no-toc epub opens");
    assert_eq!(book.chapter_count(), 2);
    assert_eq!(book.toc().len(), 2);
    assert_eq!(book.toc()[0].label, "Chapter 1");
    assert_eq!(book.toc()[1].label, "Chapter 2");
    assert_eq!(book.toc()[1].chapter_index, Some(1));
    let _ = std::fs::remove_file(&path);
}

#[test]
fn synthetic_empty_spine_is_an_error() {
    let manifest = item_xml("c1", "c1.xhtml", "application/xhtml+xml");
    let path = temp_epub(
        "empty-spine",
        &opf2("Empty Spine", &manifest, ""),
        &[("OEBPS/c1.xhtml", chapter_bytes("Unreachable"))],
    );
    let err = Book::open(&path).expect_err("empty spine must be rejected");
    assert!(
        err.to_string().contains("spine"),
        "unexpected error: {err}"
    );
    let _ = std::fs::remove_file(&path);
}

#[test]
fn synthetic_toc_entries_outside_spine_get_no_chapter() {
    let manifest = [
        item_xml("ncx", "toc.ncx", "application/x-dtbncx+xml"),
        item_xml("c1", "c1.xhtml", "application/xhtml+xml"),
        // In the manifest but not in the spine.
        item_xml("orphan", "orphan.xhtml", "application/xhtml+xml"),
    ]
    .concat();
    let spine = "<itemref idref=\"c1\"/>";
    let ncx = r#"<?xml version="1.0" encoding="UTF-8"?>
<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">
  <head><meta name="dtb:uid" content="urn:uuid:temp"/></head>
  <docTitle><text>Outside</text></docTitle>
  <navMap>
    <navPoint id="a" playOrder="1"><navLabel><text>Real</text></navLabel><content src="c1.xhtml"/></navPoint>
    <navPoint id="b" playOrder="2"><navLabel><text>Ghost</text></navLabel><content src="ghost.xhtml"/></navPoint>
    <navPoint id="c" playOrder="3"><navLabel><text>Orphan</text></navLabel><content src="orphan.xhtml"/></navPoint>
  </navMap>
</ncx>"#;
    let path = temp_epub(
        "toc-outside-spine",
        &opf2("Outside", &manifest, spine),
        &[
            ("OEBPS/c1.xhtml", chapter_bytes("Real")),
            ("OEBPS/orphan.xhtml", chapter_bytes("Orphan")),
            ("OEBPS/toc.ncx", ncx.as_bytes().to_vec()),
        ],
    );
    let book = Book::open(&path).expect("toc-outside epub opens");
    assert_eq!(book.chapter_count(), 1);
    let by_label = |label: &str| {
        book.toc()
            .iter()
            .find(|t| t.label == label)
            .unwrap_or_else(|| panic!("missing toc label {label}"))
            .chapter_index
    };
    assert_eq!(by_label("Real"), Some(0));
    assert_eq!(by_label("Ghost"), None);
    assert_eq!(by_label("Orphan"), None);
    let _ = std::fs::remove_file(&path);
}

#[test]
fn synthetic_non_utf8_chapter_decodes_with_fallback() {
    // Windows-1252 bytes: "café — naïve" with 0xE9/0x97/0xEF. Declared via <meta charset>,
    // the loader must decode instead of failing (rbook's read_resource_str is UTF-8 only).
    let mut xhtml = Vec::new();
    xhtml.extend_from_slice(
        b"<?xml version=\"1.0\" encoding=\"windows-1252\"?><html><head><meta charset=\"windows-1252\"/></head><body>",
    );
    xhtml.extend_from_slice(b"<p>caf");
    xhtml.push(0xE9);
    xhtml.extend_from_slice(b" \x97 na");
    xhtml.push(0xEF);
    xhtml.extend_from_slice(b"ve</p></body></html>");
    let manifest = item_xml("c1", "c1.xhtml", "application/xhtml+xml");
    let path = temp_epub(
        "non-utf8",
        &opf2("Legacy", &manifest, "<itemref idref=\"c1\"/>"),
        &[("OEBPS/c1.xhtml", xhtml)],
    );
    let book = Book::open(&path).expect("non-utf8 epub opens");
    let decoded = book
        .resource_str(0, "c1.xhtml")
        .expect("chapter bytes decode with fallback encoding");
    assert!(
        decoded.contains("café") && decoded.contains("naïve"),
        "fallback decoding failed: {decoded}"
    );
    let _ = std::fs::remove_file(&path);
}

