fn book_is_send_and_sync() {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<Book>();
}

#[test]
fn synthetic_drm_protected_epub_is_rejected_with_clear_error() {
    let manifest = item_xml("c1", "c1.xhtml", "application/xhtml+xml");
    let encryption = r#"<?xml version="1.0" encoding="UTF-8"?>
<encryption xmlns="urn:oasis:names:tc:opendocument:xmlns:container"
            xmlns:enc="http://www.w3.org/2001/04/xmlenc#">
  <enc:EncryptedData>
    <enc:EncryptionMethod Algorithm="http://www.w3.org/2001/04/xmlenc#aes256-cbc"/>
    <enc:CipherData><enc:CipherReference URI="OEBPS/c1.xhtml"/></enc:CipherData>
  </enc:EncryptedData>
</encryption>"#;
    let path = temp_epub(
        "drm",
        &opf2("DRM", &manifest, "<itemref idref=\"c1\"/>"),
        &[
            ("OEBPS/c1.xhtml", chapter_bytes("Locked")),
            ("META-INF/encryption.xml", encryption.as_bytes().to_vec()),
        ],
    );
    let err = Book::open(&path).expect_err("DRM-protected epub must be rejected");
    assert!(
        err.to_string().to_ascii_lowercase().contains("drm"),
        "error should explain DRM: {err}"
    );
    let _ = std::fs::remove_file(&path);
}

// ---------------------------------------------------------------------------
// Task 7 — CSS subset: parsing, specificity, cascade, colors, UA defaults
// ---------------------------------------------------------------------------

use epub_reader::epub::css::{ComputedStyle, Stylesheet, parse_color};
use epub_reader::epub::model::TextAlignment;

fn element(html: &str, selector: &str) -> scraper::ElementRef<'static> {
    let doc: &'static scraper::Html = Box::leak(Box::new(scraper::Html::parse_document(html)));
    let selector = scraper::Selector::parse(selector).expect("valid selector");
    doc.select(&selector).next().expect("element present")
}

fn cascade(html: &str, selector: &str, css: &str, parent: &ComputedStyle) -> ComputedStyle {
    let sheet = Stylesheet::parse(css);
    let el = element(html, selector);
    sheet.cascade_for(&el, el.attr("style"), parent, parent)
}

/// Compares an `Hsla` (which does not implement `PartialEq`) with an expected RGB hex.
fn assert_color(actual: Option<gpui::Hsla>, expected: u32) {
    let actual = actual.unwrap_or_else(|| panic!("expected color #{expected:06x}, got None"));
    let expected = gpui::Hsla::from(gpui::rgb(expected));
    for (name, a, e) in [
        ("h", actual.h, expected.h),
        ("s", actual.s, expected.s),
        ("l", actual.l, expected.l),
        ("a", actual.a, expected.a),
    ] {
        assert!(
            (a - e).abs() < 1e-4,
            "color component {name} differs: {a} vs {e}"
        );
    }
}

#[test]
fn parses_rules_and_specificity() {
    let sheet = Stylesheet::parse("p { color: #ff0000 } .x { color: #00ff00 } #y { color: #0000ff }");
    assert_eq!(sheet.rules.len(), 3);
    assert_eq!(sheet.rules[0].selectors[0].specificity(), 1);
    assert_eq!(sheet.rules[1].selectors[0].specificity(), 10);
    assert_eq!(sheet.rules[2].selectors[0].specificity(), 100);
}

#[test]
fn cascade_inline_wins_and_important() {
    let parent = ComputedStyle::default_with(16.0);
    // Later `!important` rule beats an earlier normal rule.
    let sheet = Stylesheet::parse("p { font-size: 20px; } p { font-size: 22px !important; }");
    let el = element(r#"<html><body><p class="x">t</p></body></html>"#, "p");
    assert_eq!(
        sheet
            .cascade_for(&el, el.attr("style"), &parent, &parent)
            .font_size,
        22.0
    );

    // Inline style beats normal author rules.
    let sheet = Stylesheet::parse("p { font-size: 20px; }");
    let el = element(
        r#"<html><body><p style="font-size: 25px">t</p></body></html>"#,
        "p",
    );
    assert_eq!(
        sheet
            .cascade_for(&el, el.attr("style"), &parent, &parent)
            .font_size,
        25.0
    );

    // ... but an `!important` author rule beats a normal inline style.
    let sheet = Stylesheet::parse("p { font-size: 22px !important; }");
    assert_eq!(
        sheet
            .cascade_for(&el, el.attr("style"), &parent, &parent)
            .font_size,
        22.0
    );
}

#[test]
fn unit_conversions() {
    let parent = ComputedStyle::default_with(20.0);
    let style = cascade(
        "<html><body><p>t</p></body></html>",
        "p",
        "p { font-size: 1.5em; text-indent: 2em; margin-top: 1em; }",
        &parent,
    );
    assert_eq!(style.font_size, 30.0);
    // CSS: `em` in non-font properties resolves against the element's own font-size (2 x 30 = 60),
    // not the parent's (40); browsers behave the same way.
    assert_eq!(style.indent, 60.0);
    assert_eq!(style.margin_top, 30.0);
    assert_eq!(style.to_block_style().space_before, 30.0);
}

#[test]
fn percent_and_keyword_font_sizes() {
    let parent = ComputedStyle::default_with(20.0);
    let html = "<html><body><p>t</p></body></html>";
    let style = cascade(html, "p", "p { font-size: 150% }", &parent);
    assert_eq!(style.font_size, 30.0);
    let style = cascade(html, "p", "p { font-size: small }", &parent);
    assert!((style.font_size - 16.6).abs() < 0.1);
}

#[test]
fn parse_colors() {
    assert_color(parse_color("#fff"), 0xffffff);
    assert_color(parse_color("#ffffff"), 0xffffff);
    assert_color(parse_color("#123456"), 0x123456);
    assert_color(parse_color("rgb(255, 0, 0)"), 0xff0000);
    assert_color(parse_color("rgb(0 128 255)"), 0x0080ff);
    assert_color(parse_color("rebeccapurple"), 0x663399);
    assert_color(parse_color("RED"), 0xff0000);
    assert_eq!(parse_color("nonsense"), None);
    assert_eq!(parse_color("currentcolor"), None);
    let translucent = parse_color("rgba(0, 0, 0, 0.5)").expect("rgba parses");
    assert!((translucent.a - 0.5).abs() < 0.01);
}

#[test]
fn display_none_and_align() {
    let parent = ComputedStyle::default_with(16.0);
    let hidden = cascade(
        r#"<html><body><div class="hidden">x</div></body></html>"#,
        "div",
        ".hidden { display: none }",
        &parent,
    );
    assert!(hidden.display_none);
    let centered = cascade(
        r#"<html><body><p class="c">x</p></body></html>"#,
        "p",
        ".c { text-align: center }",
        &parent,
    );
    assert_eq!(centered.align, TextAlignment::Center);
    let right = cascade(
        r#"<html><body><p style="text-align: right">x</p></body></html>"#,
        "p",
        "",
        &parent,
    );
    assert_eq!(right.align, TextAlignment::End);
}

#[test]
fn descendant_and_attribute_selectors() {
    let sheet = Stylesheet::parse("div p { color: #00ff00 } a[href] { color: #0000ff } [lang] { font-style: italic }");
    let html = r#"<html><body><div><section><p>deep</p></section></div>
        <p>shallow</p><a href="x">link</a><span lang="vi">v</span></body></html>"#;
    let deep = element(html, "div p");
    let mut matched = Vec::new();
    sheet.matching_rules(&deep, &mut matched);
    assert_eq!(matched.len(), 1, "descendant combinator should match");
    let link = element(html, "a");
    let mut matched = Vec::new();
    sheet.matching_rules(&link, &mut matched);
    assert_eq!(matched.len(), 1, "attribute presence selector should match");
    let shallow = element(html, "body > p");
    let mut matched = Vec::new();
    sheet.matching_rules(&shallow, &mut matched);
    assert_eq!(matched.len(), 0, "descendant selector must not leak to siblings");
}

#[test]
fn margin_shorthand_and_border() {
    let parent = ComputedStyle::default_with(20.0);
    let style = cascade(
        "<html><body><p>t</p></body></html>",
        "p",
        "p { margin: 10px 20px 30px 40px; padding: 5px 15px; border-left: 2px solid #333 }",
        &parent,
    );
    assert_eq!(
        (
            style.margin_top,
            style.margin_right,
            style.margin_bottom,
            style.margin_left
        ),
        (10.0, 20.0, 30.0, 40.0)
    );
    assert_eq!((style.padding_left, style.padding_right), (15.0, 15.0));
    let (width, color) = style.border_left.expect("border parsed");
    assert_eq!(width, 2.0);
    assert_color(Some(color), 0x333333);
}

#[test]
fn ignores_at_rules_and_comments() {
    let sheet = Stylesheet::parse(
        "/* c */ @media screen { p { color: red } } @font-face { font-family: X } p { color: #00ff00 }",
    );
    assert_eq!(sheet.rules.len(), 1);
    assert_eq!(sheet.rules[0].declarations[0].name, "color");
}

#[test]
fn ua_defaults_are_applied_before_author_rules() {
    let parent = ComputedStyle::default_with(16.0);
    // No author rules: <h1> is 2em bold from the UA sheet.
    let style = cascade("<html><body><h1>T</h1></body></html>", "h1", "", &parent);
    assert_eq!(style.font_size, 32.0);
    assert!(style.bold);
    // Author rules override the UA sheet.
    let style = cascade(
        "<html><body><h1>T</h1></body></html>",
        "h1",
        "h1 { font-size: 18px; font-weight: normal }",
        &parent,
    );
    assert_eq!(style.font_size, 18.0);
    assert!(!style.bold);
}

// ---------------------------------------------------------------------------
// Task 8 — XHTML → BlockModel walker
// ---------------------------------------------------------------------------

use epub_reader::epub::model::{Block, Inline};
use epub_reader::epub::xhtml::parse_html_fragment;

fn blocks(html: &str) -> Vec<Block> {
    parse_html_fragment(html, 16.0)
        .expect("fragment parses")
        .blocks
}

fn text_of(runs: &[Inline]) -> String {
    runs.iter()
        .filter_map(|run| run.text().map(|(text, _)| text.to_string()))
        .collect()
}

#[test]
fn paragraphs_and_inline_emphasis() {
    let parsed = blocks(
        r#"<body><p>Hello <b>bold</b> and <i>italic</i> and <code>code</code>.</p></body>"#,
    );
    assert_eq!(parsed.len(), 1);
    let Block::Paragraph { runs, .. } = &parsed[0] else {
        panic!("expected paragraph")
    };
    assert_eq!(text_of(runs), "Hello bold and italic and code.");
    assert!(runs
        .iter()
        .any(|run| matches!(run, Inline::Text { style, .. } if style.bold)));
    assert!(runs
        .iter()
        .any(|run| matches!(run, Inline::Text { style, .. } if style.italic)));
    assert!(runs
        .iter()
        .any(|run| matches!(run, Inline::Text { style, .. } if style.code)));
}

#[test]
fn lists_and_nested_lists() {
    let parsed = blocks(r#"<body><ul><li>One</li><li>Two<ul><li>Nested</li></ul></li></ul></body>"#);
    assert!(matches!(parsed[0], Block::List(_)));
    let Block::List(list) = &parsed[0] else {
        unreachable!()
    };
    assert_eq!(list.items.len(), 2);
    assert!(!list.items[1].blocks.is_empty());
    assert_eq!(list.items[0].marker, "\u{2022}");
    assert_eq!(text_of(&list.items[0].runs), "One");
    assert_eq!(text_of(&list.items[1].runs), "Two");
}

#[test]
fn ordered_list_start_attribute() {
    let parsed = blocks(r#"<body><ol start="3"><li>Third</li><li>Fourth</li></ol></body>"#);
    let Block::List(list) = &parsed[0] else {
        unreachable!()
    };
    assert!(list.ordered);
    assert_eq!(list.start, 3);
    assert_eq!(list.items[0].marker, "3.");
    assert_eq!(list.items[1].marker, "4.");
}

#[test]
fn blockquote_pre_and_hr() {
    let parsed = blocks(
        "<body><blockquote><p>Q</p></blockquote><pre>line 1\nline 2</pre><hr/></body>",
    );
    assert!(matches!(parsed[0], Block::Quote { .. }));
    assert!(matches!(
        parsed[1],
        Block::Preformatted { ref text, .. } if text == "line 1\nline 2"
    ));
    assert!(matches!(parsed[2], Block::Rule));
}

#[test]
fn images_and_tables() {
    let parsed = blocks(
        r#"<body><p><img src="Images/c%20over.png" alt="cover" width="120"/></p>
        <table><tr><th>A</th><th>B</th></tr><tr><td>1</td><td>2</td></tr></table></body>"#,
    );
    let image = parsed
        .iter()
        .find_map(|block| match block {
            Block::Image(image) => Some(image),
            _ => None,
        })
        .expect("image block");
    assert_eq!(image.src, "Images/c%20over.png");
    assert_eq!(image.alt, "cover");
    assert_eq!(image.width, Some(120.0));
    let table = parsed
        .iter()
        .find_map(|block| match block {
            Block::Table(table) => Some(table),
            _ => None,
        })
        .expect("table block");
    assert_eq!(table.rows.len(), 2);
    assert_eq!(table.rows[0].cells.len(), 2);
    assert!(table.rows[0].cells[0].header);
    assert!(!table.rows[1].cells[0].header);
    assert_eq!(text_of(&table.rows[1].cells[1].runs), "2");
}

#[test]
fn display_none_removed_and_style_attr_applies() {
    let parsed = blocks(
        r#"<body><p style="color:#ff0000; text-indent: 2em">styled</p>
        <p class="hidden">gone</p><style>.hidden { display: none }</style></body>"#,
    );
    assert_eq!(parsed.len(), 1);
    let Block::Paragraph { style, runs } = &parsed[0] else {
        unreachable!()
    };
    assert_eq!(text_of(runs), "styled");
    assert_eq!(style.indent, 32.0);
    assert!(style.color.is_some());
}

#[test]
fn breaks_and_whitespace_collapse() {
    let parsed = blocks("<body><p>a<br/>b\n   c</p></body>");
    let Block::Paragraph { runs, .. } = &parsed[0] else {
        unreachable!()
    };
    assert!(runs.iter().any(|run| matches!(run, Inline::Break)));
    // Whitespace runs collapse to one space: "a" + <br> + "b   c" -> "a" + "b c".
    assert_eq!(text_of(runs), "ab c");
}

#[test]
fn headings_use_ua_sizes() {
    let parsed = blocks(r#"<body><h1>Title</h1><h2>Sub</h2><h3>Small</h3><h4>Four</h4></body>"#);
    let heading = |level: u8| -> f32 {
        parsed
            .iter()
            .find_map(|block| match block {
                Block::Heading {
                    level: found,
                    style,
                    ..
                } if *found == level => Some(style.font_size),
                _ => None,
            })
            .unwrap_or_else(|| panic!("heading {level} missing"))
    };
    assert_eq!(heading(1), 32.0);
    assert_eq!(heading(2), 24.0);
    assert!((heading(3) - 18.72).abs() < 0.01);
    assert_eq!(heading(4), 16.0);
}

