// ---------------------------------------------------------------------------
// Task 8 — chapter parsing through the real loader (CSS + XHTML together)
// ---------------------------------------------------------------------------

fn chapter_text(model: &epub_reader::epub::model::BlockModel) -> String {
    fn collect_block(block: &Block, out: &mut Vec<String>) {
        match block {
            Block::Heading { runs, .. } | Block::Paragraph { runs, .. } => out.push(text_of(runs)),
            Block::List(list) => {
                for item in &list.items {
                    out.push(text_of(&item.runs));
                    for nested in &item.blocks {
                        collect_block(nested, out);
                    }
                }
            }
            Block::Quote { blocks, .. } => {
                for nested in blocks {
                    collect_block(nested, out);
                }
            }
            Block::Container(container) => {
                for nested in &container.blocks {
                    collect_block(nested, out);
                }
            }
            Block::Preformatted { text, .. } => out.push(text.clone()),
            Block::Image(image) => out.push(image.alt.clone()),
            Block::Rule => {}
            Block::Table(table) => {
                for row in &table.rows {
                    for cell in &row.cells {
                        out.push(text_of(&cell.runs));
                    }
                }
            }
        }
    }
    let mut out = Vec::new();
    for block in &model.blocks {
        collect_block(block, &mut out);
    }
    out.join("\n")
}

#[test]
fn styled_fixture_chapter_applies_cascade_and_skips_hidden() {
    let book = Book::open(&fixture("styled.epub")).expect("styled opens");
    let model = book.chapter(0).expect("styled chapter parses");
    let text = chapter_text(&model);
    assert!(
        !text.contains("hidden paragraph"),
        "display:none content leaked: {text}"
    );
    assert!(text.contains("Styled Chapter"));

    // `!important` class rule wins over the inline color.
    let heading = model
        .blocks
        .iter()
        .find_map(|block| match block {
            Block::Heading { style, .. } => Some(style),
            _ => None,
        })
        .expect("heading");
    assert_color(heading.color, 0xcc0000);

    // `<p class="pre">` keeps its newline (white-space: pre from the linked stylesheet).
    let pre_paragraph = model
        .blocks
        .iter()
        .find_map(|block| match block {
            Block::Paragraph { runs, .. } if text_of(runs).starts_with("line one") => {
                Some(text_of(runs))
            }
            _ => None,
        })
        .expect("pre paragraph");
    assert!(
        pre_paragraph.contains('\n'),
        "white-space: pre not applied: {pre_paragraph:?}"
    );

    // Inline style + author rules both visible.
    let inline_paragraph = model
        .blocks
        .iter()
        .find_map(|block| match block {
            Block::Paragraph { style, runs } if text_of(runs).contains("Inline styled") => {
                Some(style)
            }
            _ => None,
        })
        .expect("inline styled paragraph");
    assert_eq!(inline_paragraph.indent, 40.0);
    assert_color(inline_paragraph.color, 0x0000ff);

    // blockquote margin 2em -> folded into padding_left (40px at the 20px base size).
    let quote = model
        .blocks
        .iter()
        .find_map(|block| match block {
            Block::Quote { style, .. } => Some(style),
            _ => None,
        })
        .expect("quote block");
    assert!(
        (quote.padding_left - 40.0).abs() < 0.01,
        "quote padding: {}",
        quote.padding_left
    );

    // Ordered list respects start="3".
    let list = model
        .blocks
        .iter()
        .find_map(|block| match block {
            Block::List(list) => Some(list),
            _ => None,
        })
        .expect("list block");
    assert_eq!((list.ordered, list.start), (true, 3));
    assert_eq!(list.items[0].marker, "3.");

    // Table with a header row.
    let table = model
        .blocks
        .iter()
        .find_map(|block| match block {
            Block::Table(table) => Some(table),
            _ => None,
        })
        .expect("table block");
    assert_eq!(table.rows.len(), 2);
    assert!(table.rows[0].cells[0].header);

    // Percent-encoded image href is preserved verbatim for Book::image_bytes.
    let image = model
        .blocks
        .iter()
        .find_map(|block| match block {
            Block::Image(image) => Some(image),
            _ => None,
        })
        .expect("image block");
    assert_eq!(image.src, "Images/c%20over.png");
    assert_eq!(image.width, Some(120.0));
}

