#[test]
fn image_bytes_resolves_parent_relative_paths() {
    // Synthetic book whose chapter lives in a subdirectory and references ../Images/...
    let manifest = [
        item_xml("c1", "text/c1.xhtml", "application/xhtml+xml"),
        item_xml("pic", "Images/pic.png", "image/png"),
        item_xml("ncx", "toc.ncx", "application/x-dtbncx+xml"),
    ]
    .concat();
    let ncx = r#"<?xml version="1.0" encoding="UTF-8"?>
<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">
  <head><meta name="dtb:uid" content="urn:uuid:temp"/></head>
  <docTitle><text>Nested</text></docTitle>
  <navMap><navPoint id="a" playOrder="1"><navLabel><text>One</text></navLabel><content src="text/c1.xhtml"/></navPoint></navMap>
</ncx>"#;
    let path = temp_epub(
        "nested-image",
        &opf2("Nested", &manifest, "<itemref idref=\"c1\"/>"),
        &[
            (
                "OEBPS/text/c1.xhtml",
                chapter_bytes("<img src=\"../Images/pic.png\" alt=\"pic\"/>"),
            ),
            ("OEBPS/Images/pic.png", png_1x1()),
            ("OEBPS/toc.ncx", ncx.as_bytes().to_vec()),
        ],
    );
    let book = Book::open(&path).expect("nested epub opens");
    assert_eq!(
        book.image_bytes(0, "../Images/pic.png").expect("resolves"),
        png_1x1()
    );
    // Root-relative hrefs address the container root.
    assert_eq!(
        book.image_bytes(0, "/OEBPS/Images/pic.png")
            .expect("root-relative resolves"),
        png_1x1()
    );
    let _ = std::fs::remove_file(&path);
}

