fn png_1x1() -> Vec<u8> {
    // Same 1x1 PNG constant used by scripts/make-fixtures.js.
    base64_decode(
        "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==",
    )
}

fn base64_decode(input: &str) -> Vec<u8> {
    const ALPHABET: &[u8; 64] =
        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = Vec::new();
    let mut buffer = 0u32;
    let mut bits = 0u32;
    for byte in input.bytes() {
        if byte == b'=' {
            break;
        }
        let Some(value) = ALPHABET.iter().position(|&candidate| candidate == byte) else {
            continue;
        };
        buffer = (buffer << 6) | value as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            output.push((buffer >> bits) as u8);
        }
    }
    output
}

// ---------------------------------------------------------------------------
// Synthetic EPUB builder (in-memory ZIP, store method) for edge-case fixtures.
// ---------------------------------------------------------------------------

const CONTAINER_XML: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles>
    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
  </rootfiles>
</container>"#;

fn item_xml(id: &str, href: &str, media_type: &str) -> String {
    format!("<item id=\"{id}\" href=\"{href}\" media-type=\"{media_type}\"/>")
}

fn opf2(title: &str, manifest: &str, spine: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="2.0" unique-identifier="bookid">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
    <dc:title>{title}</dc:title>
    <dc:identifier id="bookid">urn:uuid:temp-{title}</dc:identifier>
    <dc:language>en</dc:language>
  </metadata>
  <manifest>{manifest}</manifest>
  <spine toc="ncx">{spine}</spine>
</package>"#
    )
}

fn chapter_bytes(text: &str) -> Vec<u8> {
    format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?><html><head><title>{text}</title></head><body><p>{text}</p></body></html>"
    )
    .into_bytes()
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xffff_ffffu32;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            crc = (crc >> 1) ^ (0xedb8_8320 & (crc & 1).wrapping_neg());
        }
    }
    !crc
}

fn store_zip(entries: &[(String, Vec<u8>)]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut central = Vec::new();
    for (name, data) in entries {
        let name = name.as_bytes();
        let crc = crc32(data);
        let offset = out.len() as u32;
        let mut local = Vec::with_capacity(30 + name.len() + data.len());
        local.extend_from_slice(&0x0403_4b50u32.to_le_bytes());
        local.extend_from_slice(&20u16.to_le_bytes());
        local.extend_from_slice(&0x0800u16.to_le_bytes());
        local.extend_from_slice(&0u16.to_le_bytes());
        local.extend_from_slice(&[0u8; 4]);
        local.extend_from_slice(&crc.to_le_bytes());
        local.extend_from_slice(&(data.len() as u32).to_le_bytes());
        local.extend_from_slice(&(data.len() as u32).to_le_bytes());
        local.extend_from_slice(&(name.len() as u16).to_le_bytes());
        local.extend_from_slice(&0u16.to_le_bytes());
        out.extend_from_slice(&local);
        out.extend_from_slice(name);
        out.extend_from_slice(data);

        central.extend_from_slice(&0x0201_4b50u32.to_le_bytes());
        central.extend_from_slice(&20u16.to_le_bytes());
        central.extend_from_slice(&20u16.to_le_bytes());
        central.extend_from_slice(&0x0800u16.to_le_bytes());
        central.extend_from_slice(&0u16.to_le_bytes());
        central.extend_from_slice(&[0u8; 4]);
        central.extend_from_slice(&crc.to_le_bytes());
        central.extend_from_slice(&(data.len() as u32).to_le_bytes());
        central.extend_from_slice(&(data.len() as u32).to_le_bytes());
        central.extend_from_slice(&(name.len() as u16).to_le_bytes());
        central.extend_from_slice(&0u16.to_le_bytes());
        central.extend_from_slice(&0u16.to_le_bytes());
        central.extend_from_slice(&0u16.to_le_bytes());
        central.extend_from_slice(&0u16.to_le_bytes());
        central.extend_from_slice(&0u32.to_le_bytes());
        central.extend_from_slice(&offset.to_le_bytes());
        central.extend_from_slice(name);
    }
    let central_offset = out.len() as u32;
    out.extend_from_slice(&central);
    out.extend_from_slice(&0x0605_4b50u32.to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes());
    out.extend_from_slice(&(entries.len() as u16).to_le_bytes());
    out.extend_from_slice(&(entries.len() as u16).to_le_bytes());
    out.extend_from_slice(&(central.len() as u32).to_le_bytes());
    out.extend_from_slice(&central_offset.to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes());
    out
}

fn temp_epub(name: &str, opf: &str, files: &[(&str, Vec<u8>)]) -> PathBuf {
    let mut entries = vec![
        ("mimetype".to_string(), b"application/epub+zip".to_vec()),
        (
            "META-INF/container.xml".to_string(),
            CONTAINER_XML.as_bytes().to_vec(),
        ),
        ("OEBPS/content.opf".to_string(), opf.as_bytes().to_vec()),
    ];
    for (path, data) in files {
        entries.push((path.to_string(), data.clone()));
    }
    let path = std::env::temp_dir().join(format!(
        "epub-reader-test-{name}-{}.epub",
        std::process::id()
    ));
    std::fs::write(&path, store_zip(&entries)).expect("write synthetic epub");
    path
}

#[test]
fn fixture_zip_headers_are_deterministic() {    // The generator must be reproducible: `mimetype` is the first entry, stored
    // uncompressed, and every header timestamp is zeroed so regeneration is byte-stable.
    let bytes = std::fs::read(fixture("minimal2.epub")).expect("fixture readable");
    assert_eq!(&bytes[0..4], b"PK\x03\x04");
    let method = u16::from_le_bytes([bytes[8], bytes[9]]);
    assert_eq!(method, 0, "mimetype entry must be stored");
    let time = u16::from_le_bytes([bytes[10], bytes[11]]);
    let date = u16::from_le_bytes([bytes[12], bytes[13]]);
    assert_eq!((time, date), (0, 0), "timestamps must be zeroed");
    let name_len = u16::from_le_bytes([bytes[26], bytes[27]]) as usize;
    assert_eq!(&bytes[30..30 + name_len], b"mimetype");
    let size = u32::from_le_bytes([bytes[18], bytes[19], bytes[20], bytes[21]]) as usize;
    assert_eq!(
        &bytes[30 + name_len..30 + name_len + size],
        b"application/epub+zip"
    );
}

// ---------------------------------------------------------------------------
// Manual robustness sweep over real-world EPUBs (gitignored downloads).
//
// Run with: cargo test --test epub_parse -- --ignored --nocapture
// (in the sandbox: `.\scripts\dev.ps1 test --test epub_parse -- --ignored --nocapture`)
// ---------------------------------------------------------------------------

fn robustness_collect_images(chapter: usize, model: &epub_reader::epub::model::BlockModel, out: &mut Vec<(usize, String)>) {
    fn walk(chapter: usize, block: &Block, out: &mut Vec<(usize, String)>) {
        match block {
            Block::Image(image) => out.push((chapter, image.src.clone())),
            Block::List(list) => {
                for item in &list.items {
                    for nested in &item.blocks {
                        walk(chapter, nested, out);
                    }
                }
            }
            Block::Quote { blocks, .. } => {
                for nested in blocks {
                    walk(chapter, nested, out);
                }
            }
            _ => {}
        }
    }
    for block in &model.blocks {
        walk(chapter, block, out);
    }
}

fn robustness_count_inline_runs(model: &epub_reader::epub::model::BlockModel) -> usize {
    fn block_runs(block: &Block) -> usize {
        match block {
            Block::Heading { runs, .. } | Block::Paragraph { runs, .. } => runs.len(),
            Block::List(list) => list
                .items
                .iter()
                .map(|item| item.runs.len() + item.blocks.iter().map(block_runs).sum::<usize>())
                .sum(),
            Block::Quote { blocks, .. } => blocks.iter().map(block_runs).sum(),
            Block::Container(container) => container.blocks.iter().map(block_runs).sum(),
            Block::Table(table) => table
                .rows
                .iter()
                .flat_map(|row| row.cells.iter())
                .map(|cell| cell.runs.len())
                .sum(),
            Block::Preformatted { .. } | Block::Image(_) | Block::Rule => 0,
        }
    }
    model.blocks.iter().map(block_runs).sum()
}

#[test]
#[ignore = "manual robustness sweep over downloaded real books; run with --ignored --nocapture"]
fn real_books_robustness_sweep() {
    use std::time::Instant;

    const BOOKS: [(&str, &str); 3] = [
        ("pride-and-prejudice.epub", "Pride and Prejudice"),
        ("alice-in-wonderland.epub", "Alice in Wonderland"),
        ("moby-dick.epub", "Moby Dick"),
    ];
    let root = Path::new("tests/fixtures/downloaded");
    let mut opened = 0usize;

    for (file, label) in BOOKS {
        let path = root.join(file);
        if !path.exists() {
            println!(
                "SKIP {label}: {path:?} not present (gitignored download; run the fetch script)"
            );
            continue;
        }
        opened += 1;

        let started = Instant::now();
        let book = Book::open(&path)
            .unwrap_or_else(|error| panic!("{label}: Book::open failed: {error:#}"));
        let open_ms = started.elapsed().as_secs_f64() * 1000.0;

        let mut chapter_errors = Vec::new();
        let mut empty_chapters = Vec::new();
        let mut total_blocks = 0usize;
        let mut total_runs = 0usize;
        let mut total_anchors = 0usize;
        let mut images: Vec<(usize, String)> = Vec::new();
        let mut per_chapter_blocks: Vec<(usize, usize)> = Vec::new();
        let parse_started = Instant::now();
        for index in 0..book.chapter_count() {
            match book.chapter(index) {
                Ok(model) => {
                    if model.blocks.is_empty() {
                        empty_chapters.push(index);
                    }
                    total_blocks += model.blocks.len();
                    total_runs += robustness_count_inline_runs(&model);
                    total_anchors += model.anchors.len();
                    per_chapter_blocks.push((index, model.blocks.len()));
                    robustness_collect_images(index, &model, &mut images);
                }
                Err(error) => chapter_errors.push(format!(
                    "chapter {index} ({}): {error:#}",
                    book.spine_href(index)
                )),
            }
        }
        let parse_ms = parse_started.elapsed().as_secs_f64() * 1000.0;
        let chapters = book.chapter_count();
        let avg_ms = if chapters == 0 {
            0.0
        } else {
            parse_ms / chapters as f64
        };

        // Materialize every referenced image (skip data URIs / SVG, which are unsupported degrades).
        let mut image_ok = 0usize;
        let mut image_skipped = 0usize;
        let mut image_errors = Vec::new();
        for (chapter, src) in &images {
            let lower = src.to_ascii_lowercase();
            if lower.starts_with("data:")
                || lower.starts_with("http:")
                || lower.starts_with("https:")
                || lower.contains(".svg")
            {
                image_skipped += 1;
                continue;
            }
            match book.image_bytes(*chapter, src) {
                Ok(bytes) if !bytes.is_empty() => image_ok += 1,
                Ok(_) => image_errors.push(format!("chapter {chapter}: empty bytes for {src}")),
                Err(error) => image_errors.push(format!("chapter {chapter}: {src}: {error:#}")),
            }
        }

        let mapped_toc = book
            .toc()
            .iter()
            .filter(|entry| entry.chapter_index.is_some())
            .count();
        let max_depth = book.toc().iter().map(|entry| entry.depth).max().unwrap_or(0);

        println!("=== {label} ({file}) ===");
        println!(
            "  open: {open_ms:.1} ms | metadata: title={:?} authors={:?}",
            book.metadata().title,
            book.metadata().authors
        );
        println!(
            "  spine: {chapters} | toc: {} entries ({mapped_toc} mapped to spine, max depth {max_depth})",
            book.toc().len()
        );
        println!(
            "  parse all: {parse_ms:.1} ms (avg {avg_ms:.2} ms/chapter) | blocks: {total_blocks} | inline runs: {total_runs} | anchors: {total_anchors}"
        );
        println!(
            "  images: {} referenced, {image_ok} resolved, {image_skipped} skipped (data/svg), {} errors",
            images.len(),
            image_errors.len()
        );

        if std::env::var_os("EPUB_SWEEP_VERBOSE").is_some() {
            for (index, blocks) in &per_chapter_blocks {
                println!(
                    "    chapter {index:>3} ({}): {blocks} blocks",
                    book.spine_href(*index)
                );
            }
        }

        if !chapter_errors.is_empty() {
            println!("  CHAPTER ERRORS ({}):", chapter_errors.len());
            for error in &chapter_errors {
                println!("    - {error}");
            }
        }
        if !empty_chapters.is_empty() {
            println!("  EMPTY CHAPTER MODELS: {empty_chapters:?}");
        }
        if !image_errors.is_empty() {
            println!("  IMAGE ERRORS ({}):", image_errors.len());
            for error in &image_errors {
                println!("    - {error}");
            }
        }

        assert!(
            chapter_errors.is_empty(),
            "{label}: chapter parse failures: {chapter_errors:#?}"
        );
        assert!(
            empty_chapters.is_empty(),
            "{label}: chapters produced an empty BlockModel: {empty_chapters:?}"
        );
        assert!(
            image_errors.is_empty(),
            "{label}: image materialization failures: {image_errors:#?}"
        );
    }

    if opened == 0 {
        println!("no downloaded real books found under {root:?}; nothing to sweep");
    }
}


// Regression: Gutenberg EPUBs use self-closing heading anchors (`<a id="chap01"/>`). html5ever
// treats the stray `/` as ignored, so the `<a>` element stays open and ends up parenting every
// following `<p>` of the chapter. The walker must treat such an inline wrapper as a container
// instead of flattening a whole chapter into a single paragraph.
#[test]
fn self_closing_anchor_does_not_swallow_paragraphs() {
    let parsed = blocks(
        r#"<body><div class="chapter"><h2><a id="chap01"/>CHAPTER I.<br/>
        Down the Rabbit-Hole</h2>
        <p>First paragraph.</p>
        <p>Second paragraph with <i>emphasis</i>.</p>
        <p>Third paragraph.</p></div></body>"#,
    );
    let headings: Vec<&Block> = parsed
        .iter()
        .filter(|block| matches!(block, Block::Heading { .. }))
        .collect::<Vec<_>>();
    assert_eq!(headings.len(), 1, "expected one heading, got {parsed:#?}");
    let paragraphs: Vec<String> = parsed
        .iter()
        .filter_map(|block| match block {
            Block::Paragraph { runs, .. } => Some(text_of(runs)),
            _ => None,
        })
        .collect();
    assert_eq!(
        paragraphs,
        vec![
            "First paragraph.",
            "Second paragraph with emphasis.",
            "Third paragraph."
        ],
        "anchored wrapper must not merge paragraphs: {parsed:#?}"
    );
}

