#[test]
fn minimal2_nested_toc_entry_exposes_anchor() {
    let book = Book::open(&fixture("minimal2.epub")).expect("minimal2 opens");
    let section = book
        .toc()
        .iter()
        .find(|entry| entry.label.contains("Section 1"))
        .expect("nested toc entry");
    assert_eq!(section.depth, 1);
    assert_eq!(section.chapter_index, Some(0));
    assert_eq!(section.anchor.as_deref(), Some("s1"));
    // Entries without a fragment keep `anchor: None`.
    let chapter_one = book
        .toc()
        .iter()
        .find(|entry| entry.label == "Chapter 1")
        .expect("chapter 1 toc entry");
    assert_eq!(chapter_one.anchor, None);
}

#[test]
fn minimal2_chapter_model_maps_anchors_to_blocks() {
    let book = Book::open(&fixture("minimal2.epub")).expect("minimal2 opens");
    let model = book.chapter(0).expect("chapter 0 parses");
    assert_eq!(model.anchors.get("s1"), Some(&1), "anchors: {:?}", model.anchors);
    assert_eq!(model.anchor_block("s1"), Some(1));
    // `anchor_block` accepts the TOC fragment form with `#`.
    assert_eq!(model.anchor_block("#s1"), Some(1));
    assert_eq!(model.anchor_block("missing"), None);
    let Block::Paragraph { runs, .. } = &model.blocks[1] else {
        panic!("expected the anchored paragraph at block 1: {:?}", model.blocks);
    };
    assert!(text_of(runs).contains("First chapter"));
}

