#[test]
fn toc_fragment_is_percent_decoded() {
    let manifest = [
        item_xml("ncx", "toc.ncx", "application/x-dtbncx+xml"),
        item_xml("c1", "c1.xhtml", "application/xhtml+xml"),
    ]
    .concat();
    let ncx = r#"<?xml version="1.0" encoding="UTF-8"?>
<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">
  <head><meta name="dtb:uid" content="urn:uuid:temp"/></head>
  <docTitle><text>Encoded</text></docTitle>
  <navMap>
    <navPoint id="a" playOrder="1"><navLabel><text>Top</text></navLabel><content src="c1.xhtml"/></navPoint>
    <navPoint id="b" playOrder="2"><navLabel><text>Encoded section</text></navLabel><content src="c1.xhtml#se%20c1"/></navPoint>
  </navMap>
</ncx>"#;
    let path = temp_epub(
        "encoded-fragment",
        &opf2("Encoded", &manifest, "<itemref idref=\"c1\"/>"),
        &[
            (
                "OEBPS/c1.xhtml",
                chapter_bytes("<p id=\"se c1\">Encoded target.</p>"),
            ),
            ("OEBPS/toc.ncx", ncx.as_bytes().to_vec()),
        ],
    );
    let book = Book::open(&path).expect("encoded-fragment epub opens");
    let encoded = book
        .toc()
        .iter()
        .find(|entry| entry.label == "Encoded section")
        .expect("encoded toc entry");
    assert_eq!(encoded.chapter_index, Some(0));
    assert_eq!(encoded.anchor.as_deref(), Some("se c1"));
    let model = book.chapter(0).expect("chapter parses");
    assert_eq!(model.anchor_block("se c1"), Some(0));
    let _ = std::fs::remove_file(&path);
}

