#[test]
fn parses_inline_links_and_anchor_targets() {
    use epub_reader::epub::model::{Block, Inline};

    let html = r##"<html><body>
        <p>Bấm vào <a href="#muc-1">mục một</a> để tới đích.</p>
        <h2 id="muc-1">Mục một</h2>
    </body></html>"##;
    let model = epub_reader::epub::xhtml::parse_html_fragment(html, 20.0).expect("fragment parses");
    let mut link = None;
    for block in &model.blocks {
        if let Block::Paragraph { runs, .. } = block {
            for run in runs {
                if let Inline::Link { text, href, .. } = run {
                    link = Some((text.clone(), href.clone()));
                }
            }
        }
    }
    assert_eq!(link, Some(("mục một".to_string(), "#muc-1".to_string())));
    assert_eq!(model.anchors.get("muc-1").copied(), Some(1));
}

#[test]
fn resolve_href_handles_fragments_spine_paths_and_external_urls() {
    let book = Book::open(&fixture("minimal2.epub")).expect("minimal2 opens");
    assert_eq!(
        book.resolve_href(0, "#frag"),
        Some((0, Some("frag".to_string())))
    );
    assert_eq!(book.resolve_href(0, "https://example.com/x"), None);
    assert_eq!(book.resolve_href(0, "mailto:a@b.c"), None);
    // A link to another spine resource resolves to that chapter (fragment optional).
    let second = book.spine_href(1).to_string();
    assert_eq!(book.resolve_href(0, &second), Some((1, None)));
}


